/* ═══════════════════════════════════════════════════════
   LIVE BACKGROUND — floating glowing orbs
═══════════════════════════════════════════════════════ */
function LiveBackground() {
  const canvasRef = useRef(null);
  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext("2d");
    let animId, W, H;

    const COLORS = [
      { r:245, g:197, b:24  },
      { r:232, g:105, b:10  },
      { r:245, g:156, b:24  },
      { r:255, g:70,  b:0   },
      { r:255, g:220, b:0   },
    ];
    const orbs = [];
    const N = 18;
    const rand = (a,b) => a + Math.random()*(b-a);

    function resize() {
      W = canvas.width  = window.innerWidth;
      H = canvas.height = window.innerHeight;
    }
    function initOrbs() {
      orbs.length = 0;
      for (let i = 0; i < N; i++) {
        const c = COLORS[Math.floor(Math.random()*COLORS.length)];
        orbs.push({
          x: rand(0,W), y: rand(0,H),
          r: rand(120,340),
          vx: rand(-0.35,0.35), vy: rand(-0.25,0.25),
          baseAlpha: rand(0.045,0.12), alpha: 0,
          pulseSpeed: rand(0.008,0.018),
          pulseOffset: rand(0,Math.PI*2),
          cr:c.r, cg:c.g, cb:c.b,
          wobbleAmp: rand(0,0.4),
          wobbleSpeed: rand(0.01,0.03),
          wobblePhase: rand(0,Math.PI*2),
          t: 0,
        });
      }
    }
    function draw() {
      ctx.clearRect(0,0,W,H);
      ctx.fillStyle="#080808";
      ctx.fillRect(0,0,W,H);
      orbs.forEach(o => {
        o.t++;
        o.x += o.vx; o.y += o.vy;
        if (o.x < -o.r)    o.x = W+o.r;
        if (o.x > W+o.r)   o.x = -o.r;
        if (o.y < -o.r)    o.y = H+o.r;
        if (o.y > H+o.r)   o.y = -o.r;
        const pulse = 0.5+0.5*Math.sin(o.t*o.pulseSpeed+o.pulseOffset);
        o.alpha = o.baseAlpha*(0.6+0.4*pulse);
        const wobble = 1+o.wobbleAmp*Math.sin(o.t*o.wobbleSpeed+o.wobblePhase);
        const radius = o.r*wobble;
        const g = ctx.createRadialGradient(o.x,o.y,0,o.x,o.y,radius);
        g.addColorStop(0,  `rgba(${o.cr},${o.cg},${o.cb},${(o.alpha*1.6).toFixed(3)})`);
        g.addColorStop(0.3,`rgba(${o.cr},${o.cg},${o.cb},${(o.alpha*0.8).toFixed(3)})`);
        g.addColorStop(0.7,`rgba(${o.cr},${o.cg},${o.cb},${(o.alpha*0.2).toFixed(3)})`);
        g.addColorStop(1,  `rgba(${o.cr},${o.cg},${o.cb},0)`);
        ctx.beginPath();
        ctx.arc(o.x,o.y,radius,0,Math.PI*2);
        ctx.fillStyle=g;
        ctx.fill();
      });
      animId = requestAnimationFrame(draw);
    }
    resize(); initOrbs(); animId = requestAnimationFrame(draw);
    const onResize = () => resize();
    window.addEventListener("resize", onResize);
    return () => { cancelAnimationFrame(animId); window.removeEventListener("resize",onResize); };
  }, []);
  return <canvas ref={canvasRef} style={{ position:"fixed",inset:0,zIndex:0,pointerEvents:"none",width:"100%",height:"100%" }} />;
}

